export default function prepareLeadRatings({ events }) {
  if (!Array.isArray(events)) throw new Error("Expected all new-row events.");
  const keys = ["Timestamp", "Email Address", "Your name", "Your business area", "Your team size"];
  const leads = events.map((event, index) => {
    const row = event?.row;
    if (!row || typeof row !== "object" || Array.isArray(row))
      throw new Error("Each event needs its original row.");
    if (!row.Timestamp) throw new Error("A lead needs a nonempty Timestamp match key.");
    for (const key of keys)
      if (row[key] != null && typeof row[key] === "object")
        throw new Error("Lead cells must be scalar values.");
    return {
      index,
      row: { ...row },
      timestamp: String(row.Timestamp),
      prompt:
        "Here's a lead info:\nName: " +
        String(row["Your name"] || "") +
        "\nEmail: " +
        String(row["Email Address"] || "") +
        "\nBusiness area: " +
        String(row["Your business area"] || "") +
        "\nSize of the team: " +
        String(row["Your team size"] || ""),
    };
  });
  return { leads, count: leads.length };
}

