export default function collectLeadRatings({ leads, previousState, response }) {
  if (!Array.isArray(leads)) throw new Error("Expected all selected leads.");
  const state = previousState == null ? { next: 0, results: [] } : structuredClone(previousState);
  if (
    !Number.isInteger(state.next) ||
    !Array.isArray(state.results) ||
    state.results.length !== state.next ||
    state.next > leads.length
  )
    throw new Error("Invalid lead rating progress.");
  if (state.awaiting === true) {
    if (
      !response ||
      typeof response !== "object" ||
      !["qualified", "not qualified"].includes(response.rating) ||
      typeof response.explanation !== "string"
    )
      throw new Error("The model must return a valid rating and explanation.");
    const lead = leads[state.next];
    state.results.push({
      index: lead.index,
      timestamp: lead.timestamp,
      row: lead.row,
      rating: response.rating,
      explanation: response.explanation,
    });
    state.next++;
    state.awaiting = false;
  }
  if (state.next === leads.length)
    return { state, more: false, prompt: "", results: state.results, count: state.results.length };
  state.awaiting = true;
  return {
    state,
    more: true,
    prompt: leads[state.next].prompt,
    results: state.results,
    count: state.results.length,
  };
}

