export default function planLeadRatingWrites({ values, results, sheetName }) {
  if (
    !Array.isArray(values) ||
    !Array.isArray(results) ||
    typeof sheetName !== "string" ||
    !sheetName
  )
    throw new Error("Invalid lead rating write inputs.");
  const headers = values[0];
  if (!Array.isArray(headers)) throw new Error("Missing sheet header.");
  const timestamp = headers.indexOf("Timestamp"),
    rating = headers.indexOf("Rating");
  if (
    timestamp < 0 ||
    rating < 0 ||
    headers.lastIndexOf("Timestamp") !== timestamp ||
    headers.lastIndexOf("Rating") !== rating
  )
    throw new Error("Use exactly one Timestamp and one Rating header.");
  const rows = new Map();
  for (let i = 1; i < values.length; i++) {
    if (!Array.isArray(values[i])) throw new Error("Invalid sheet row.");
    const key = values[i][timestamp];
    if (key != null && !rows.has(String(key))) rows.set(String(key), i + 1);
  }
  const sheet = "'" + sheetName.replaceAll("'", "''") + "'",
    column = (n) => {
      let text = "";
      for (n++; n; n = Math.floor((n - 1) / 26))
        text = String.fromCharCode(65 + ((n - 1) % 26)) + text;
      return text;
    },
    data = [],
    unmatched = [];
  for (const result of results) {
    if (
      !result ||
      typeof result.timestamp !== "string" ||
      !["qualified", "not qualified"].includes(result.rating) ||
      typeof result.explanation !== "string"
    )
      throw new Error("Invalid completed rating.");
    const row = rows.get(result.timestamp);
    if (row == null) {
      unmatched.push(result.index);
      continue;
    }
    data.push({ range: sheet + "!" + column(rating) + row, values: [[result.rating]] });
  }
  return {
    data,
    hasUpdates: data.length > 0,
    expectedCells: data.length,
    matched: data.length,
    unmatched,
    results,
  };
}

