export default function leadRatingRequest({ data }) {
  if (!Array.isArray(data) || data.length === 0)
    throw new Error("The selected write needs at least one Rating cell.");
  for (const entry of data) {
    if (
      typeof entry.range !== "string" ||
      !entry.range ||
      !Array.isArray(entry.values) ||
      entry.values.length !== 1 ||
      !Array.isArray(entry.values[0]) ||
      entry.values[0].length !== 1 ||
      !["qualified", "not qualified"].includes(entry.values[0][0])
    )
      throw new Error("Invalid Rating cell request.");
  }
  return { data };
}

