export default function leadRatingReceipt({
  results,
  matched,
  unmatched,
  expectedCells,
  actualCells,
}) {
  if (
    !Array.isArray(results) ||
    !Array.isArray(unmatched) ||
    !Number.isInteger(matched) ||
    !Number.isInteger(expectedCells)
  )
    throw new Error("Invalid rating receipt.");
  if (expectedCells > 0 && actualCells !== expectedCells)
    throw new Error("Rating update receipt does not match the requested cells.");
  return { rated: results.length, updated: matched, unmatched, results };
}
